"""Recompute scope-aligned final-forward metrics from collector-runs.json.

Uses only declared scope coordinates; dense valid_lengths exclude padding and
raw shards are reordered by their row indexes. Error metrics flatten paired
finite components in float64. L2 is the unnormalized Euclidean error norm.
Missing/nonfinite values always prevent complete equality.
"""
from pathlib import Path
from datetime import datetime, timezone
import hashlib
import json
import numpy as np

ROOT = Path(__file__).resolve().parent

def read(path):
    return json.loads(path.read_text())

def coord(item):
    return item['sample'], item['position']

def load(folder, expected, width):
    index = read(folder / 'index.json')
    assert index['width'] == width
    rows, sources, files = {}, {}, [folder / 'scope.json', folder / 'index.json']
    padding = 0
    def add(key, vector, source):
        assert key not in rows, f'duplicate coordinate {key}'
        assert vector.shape == (width,), (key, vector.shape)
        rows[key] = vector.astype(np.float64)
        sources[key] = source
    if index['format'] == 'dense-npz':
        path = folder / index['file']; files.append(path)
        with np.load(path, allow_pickle=False) as data:
            a = data[index['array']]
            assert a.ndim == 3 and a.shape[2] == width
            assert a.dtype == np.dtype(index['dtype'])
            assert len(index['valid_lengths']) == a.shape[0]
            for s, length in enumerate(index['valid_lengths']):
                assert 0 <= length <= a.shape[1]
                padding += a.shape[1] - length
                for p in range(length):
                    add((s,p), a[s,p], {'file':str(path.relative_to(ROOT)), 'array':index['array'], 'index':[s,p]})
    elif index['format'] == 'indexed-raw-shards':
        for shard in index['shards']:
            path = folder / shard['file']; files.append(path)
            shape = shard['shape']; dtype = np.dtype(index['dtype'])
            assert len(shape) == 2 and shape[1] == width and shape[0] == len(shard['rows'])
            assert path.stat().st_size == int(np.prod(shape)) * dtype.itemsize
            a = np.fromfile(path, dtype=dtype).reshape(shape)
            for r, item in enumerate(shard['rows']):
                add(coord(item), a[r], {'file':str(path.relative_to(ROOT)), 'row':r})
    else:
        raise ValueError(index['format'])
    extras = sorted(set(rows) - expected)
    return rows, sources, files, padding, extras

def location(key, feature=None):
    result = {'sample':int(key[0]), 'position':int(key[1])}
    if feature is not None: result['feature'] = int(feature)
    return result

def summarize(keys, data, sources, width):
    keys = sorted(keys); total = len(keys); denominator = total * width
    side_reports = {}
    for side, rows in data.items():
        present = [k for k in keys if k in rows]
        nf = {}
        for name, predicate in [('NaN',np.isnan), ('+Inf',np.isposinf), ('-Inf',np.isneginf)]:
            places = [{**location(k,i), 'source':sources[side][k]} for k in present for i in np.flatnonzero(predicate(rows[k]))]
            nf[name] = {'count':len(places), 'locations':places}
        finite = sum(int(np.isfinite(rows[k]).sum()) for k in present)
        side_reports[side] = {'present_coordinates':len(present), 'expected_coordinates':total,
            'coordinate_coverage':len(present)/total, 'present_elements':len(present)*width,
            'expected_elements':denominator, 'finite_elements':finite, 'finite_coverage':finite/denominator,
            'missing_coordinates':[location(k) for k in keys if k not in rows], 'nonfinite':nf}
    common = [k for k in keys if all(k in data[s] for s in data)]
    xs, ys, finite_differences = [], [], []
    for k in common:
        x, y = data['cedar'][k], data['maple'][k]
        mask = np.isfinite(x) & np.isfinite(y)
        xs.extend(x[mask]); ys.extend(y[mask])
        for i in np.flatnonzero(mask & (x != y)):
            finite_differences.append({**location(k,i), 'cedar':float(x[i]), 'maple':float(y[i]), 'absolute_error':float(abs(x[i]-y[i]))})
    x, y = np.asarray(xs,dtype=np.float64), np.asarray(ys,dtype=np.float64)
    delta = x-y; norm = float(np.linalg.norm(x)*np.linalg.norm(y))
    metrics = {'max_absolute_error':float(np.max(np.abs(delta))) if len(x) else None,
        'rmse':float(np.sqrt(np.mean(delta**2))) if len(x) else None,
        'l2_error':float(np.linalg.norm(delta)) if len(x) else None,
        'cosine':float(np.dot(x,y)/norm) if norm else None}
    complete = all(v['present_coordinates']==total and all(n['count']==0 for n in v['nonfinite'].values()) for v in side_reports.values()) and not finite_differences
    return {'sides':side_reports, 'paired_coordinates':len(common), 'paired_coordinate_coverage':len(common)/total,
        'paired_finite_elements':len(x), 'paired_finite_coverage':len(x)/denominator,
        'paired_nonfinite_elements':len(common)*width-len(x), 'paired_finite_metrics':metrics,
        'finite_differences':finite_differences, 'completely_equal':complete}

def main():
    config = read(ROOT/'collector-runs.json')
    folders = {s:ROOT/p for s,p in config['runs'].items()}
    scopes = {s:read(p/'scope.json') for s,p in folders.items()}
    assert scopes['cedar'] == scopes['maple'], 'scope mismatch'
    scope = scopes['cedar']; width = scope['width']
    expected = set(map(coord,scope['expected']))
    assert len(expected)==len(scope['expected'])
    data, sources, files, layouts = {}, {}, [ROOT/'export.py', ROOT/'compare_observations.py', ROOT/'collector-runs.json'], {}
    assert hashlib.sha256((ROOT/'export.py').read_bytes()).hexdigest()==config['export_sha256']
    for side, folder in folders.items():
        rows, src, fs, padding, extras = load(folder,expected,width)
        data[side], sources[side] = rows, src; files.extend(fs)
        layouts[side] = {'excluded_padding_coordinates':padding,'out_of_scope_coordinates':[location(k) for k in extras]}
    report = {'scope':scope, 'runs':config['runs'], 'layout_checks':layouts,
        'definitions':{'coordinates':'zero-based sample/position', 'feature':'zero-based vector component',
        'coordinate_coverage':'present expected coordinates / expected coordinates',
        'finite_coverage':'finite elements / (expected coordinates * width)',
        'paired_finite_coverage':'both-finite elements / (expected coordinates * width)',
        'metrics':'flattened paired finite elements, float64; L2=sqrt(sum((cedar-maple)^2)); cosine=dot/(norm*norm); undefined metrics=null',
        'complete_equality':'full coverage, no nonfinite elements on either side, and every finite element exactly equal'},
        'global':summarize(expected,data,sources,width),
        'samples':{str(s):summarize({k for k in expected if k[0]==s},data,sources,width) for s in sorted({k[0] for k in expected})}}
    def values(a):
        return [float(v) if np.isfinite(v) else ('NaN' if np.isnan(v) else '+Inf' if v>0 else '-Inf') for v in a]
    alignment = [{**location(k), **{s:({'values':values(data[s][k]),'source':sources[s][k]} if k in data[s] else None) for s in data}} for k in sorted(expected)]
    output = ROOT / ('compare-final-forward-'+datetime.now(timezone.utc).strftime('%Y%m%dT%H%M%SZ'))
    output.mkdir(exist_ok=False)
    for name, payload in [('report.json',report),('alignment.json',alignment)]:
        (output/name).write_text(json.dumps(payload,indent=2,allow_nan=False)+'\n')
    files.extend([output/'report.json',output/'alignment.json'])
    manifest = {str(p.relative_to(ROOT)):{'sha256':hashlib.sha256(p.read_bytes()).hexdigest(),'bytes':p.stat().st_size} for p in files}
    (output/'manifest.json').write_text(json.dumps(manifest,indent=2)+'\n')
    print(json.dumps({'output':str(output),'global':report['global'],'samples':report['samples']},indent=2,allow_nan=False))

if __name__=='__main__': main()
